recipe.eq:
for each problem:
  samples[1..8]  = model(question, temperature=0.9)   # 8 independent tries
  for k in 1..8:
    vote[k]      = most_common(final_number(s) for s in samples[1..k])
# coverage by k: [0.429, 0.429, 0.500, 0.500, 0.500, 0.571, 0.571, 0.571]
